contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We deposit an amount into c from this test contract, then call withdrawAll.
    // If withdrawAll does not revert, then this test contract should receive at most the deposited amount
    // (i.e., its own balance increases by at most amount) and address(c).balance decreases by at most amount.
    // Because C does not expose its credit mapping publicly, we observe the effects via balances and revert flag.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record balances before any interaction
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // deposit amount into c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // record balances after deposit
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;

        // try to withdrawAll and observe if it reverts
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record balances after withdraw attempt
        uint finalThis = address(this).balance;
        uint finalC = address(c).balance;

        // If withdrawAll succeeded, then the receiver's balance did not increase by more than the deposited amount,
        // and c's balance did not decrease by more than the deposited amount.
        // We express this as: if not reverted then (finalThis - afterDepositThis) <= amount and (afterDepositC - finalC) <= amount.
        // Use safe comparisons without underflow by rearranging.
        assert(reverted || ((finalThis <= afterDepositThis + amount) && (finalC + amount >= afterDepositC)));
    }

    receive() external payable {}
}

