// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint finalThis = address(this).balance;
        uint finalC = address(c).balance;
        assertTrue(reverted || ((finalThis <= afterDepositThis + amount) && (finalC + amount >= afterDepositC)));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
